/*
 * THE THREAD'S RULES, ONCE (TASK-L186 §1). Every one of the four functions —
 * openThread, sendMessage (the learner's) and openThreadAsCoach, replyAsCoach
 * (the coach's) — hands this ONE request and reads ONE answer, so the limit,
 * the subject, the anchor vocabulary and who marks what read have a single
 * spelling. Ported from the product's src/lib/server/conversations/service.ts.
 *
 * WHO IS ASKING IS DECIDED BEFORE THIS NODE AND CANNOT BE CHANGED BY A CALLER.
 * The learner's half fills `learnerId` from `Caller learner` (the session) and
 * never takes one as an argument, so a learner can only ever reach their own
 * threads. The coach's half has no learner id at all: it names a thread, and
 * the thread says whose it is. `reader` is set by the calling function's own
 * graph, never by a caller.
 *
 * READ-MARKING (the product's L118, verbatim in behaviour):
 *  - OPENING marks the OTHER party's turns read, and reports which were new
 *    BEFORE marking — so the reader still sees which turn is new this once.
 *  - A reader's OWN turns are never marked (that would make "unread" mean
 *    "unwritten").
 *  - SENDING marks nothing: answering is not evidence you read the one before.
 *  - `readAt` never leaves this node. A turn carries `unread: boolean`.
 *
 * A MESSAGE IS REFUSED, NEVER TRIMMED, over 4,000 characters: half a question
 * addressed to a human reads as a whole one and neither party can tell.
 *
 * Every refusal is a REASON, not a sentence: 'too_long', 'empty',
 * 'notice-not-accepted', or 'refused' for everything else — "not yours", "not
 * there" and "not a thing a thread can be about" cannot be told apart by a
 * caller (the mcp/auth.ts rule). The log carries ids, never a body.
 */
if (Inputs.request !== undefined && Inputs.request !== null) {
  (async () => {
    /* WHAT A THREAD CAN BE ABOUT — the product's NOTE_ANCHOR_KINDS, verbatim.
       The kit's THREAD_ANCHOR_KINDS is the same list; tools/check-thread.mjs
       fails if they part company. */
    const ANCHOR_KINDS = ['lesson', 'session', 'evaluation', 'assignment', 'submission', 'message', 'signal'];
    const MAX_CHARS = 4000;
    const SUBJECT_MAX_CHARS = 80;
    const r = Inputs.request || {};
    const tag = '[dbt:Thread] ' + String(r.op || '-') + '/' + String(r.reader || '-');
    const refuse = (reason, why) => {
      Outputs.reason = reason;
      console.warn(tag + ' refused: ' + (why || reason) + ' learner=' + String(r.learnerId || '-') + ' conversation=' + String(r.conversationId || '-'));
      Outputs.failed();
    };
    const q = (c, where, limit) => Noodl.Records.query(c, where, { limit: limit || 1000, plain: true });
    const newId = () => (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random().toString(16).slice(2));
    const byTime = (a, b) => (String(a.createdAt || '') < String(b.createdAt || '') ? -1 : String(a.createdAt || '') > String(b.createdAt || '') ? 1 : 0);

    /** The first line, cut at 80 with an ellipsis — the product's deriveSubject, verbatim. */
    const deriveSubject = (body) => {
      const firstLine = (body.trim().split('\n')[0] || '').trim();
      const source = firstLine.length > 0 ? firstLine : body.trim();
      return source.length > SUBJECT_MAX_CHARS ? source.slice(0, SUBJECT_MAX_CHARS - 1).trimEnd() + '…' : source;
    };

    /** The turns as the READER sees them: unread is the other party's and not yet read. */
    const view = (messages, reader) =>
      [...messages].sort(byTime).map((m) => ({
        id: m.messageId,
        authorRole: m.authorRole === 'coach' ? 'coach' : 'learner',
        body: String(m.body || ''),
        createdAt: m.createdAt || null,
        unread: m.authorRole !== reader && (m.readAt === null || m.readAt === undefined || m.readAt === '')
      }));

    try {
      const op = String(r.op || '');
      const reader = String(r.reader || '');
      if (op !== 'open' && op !== 'send') return refuse('refused', 'unknown op');
      if (reader !== 'learner' && reader !== 'coach') return refuse('refused', 'unknown reader');

      // ── WHICH THREAD ─────────────────────────────────────────────────────
      let thread = null;
      if (reader === 'learner') {
        const learnerId = String(r.learnerId || '');
        if (!learnerId) return refuse('refused', 'no learner');
        const anchorKind = String(r.anchorKind || '');
        const anchorId = String(r.anchorId || '');
        if (ANCHOR_KINDS.indexOf(anchorKind) === -1) return refuse('refused', 'anchor kind');
        if (anchorId.indexOf(anchorKind + ':') !== 0 || anchorId.length > 300) return refuse('refused', 'anchor id');
        // One-key filters (the backend refuses two): the learner's threads, then the anchor in JS.
        const mine = await q('Conversation', { learnerId: { equalTo: learnerId } });
        thread = mine.filter((c) => c.anchorKind === anchorKind && c.anchorId === anchorId).sort(byTime).pop() || null;
        if (!thread && op === 'open') {
          Outputs.turns = [];
          Outputs.learnerId = learnerId;
          Outputs.conversationId = '';
          Outputs.done();
          return;
        }
        if (!thread) thread = { learnerId, anchorKind, anchorId, conversationId: '' };
      } else {
        const conversationId = String(r.conversationId || '');
        if (!conversationId || conversationId.length > 200) return refuse('refused', 'no conversation');
        const found = await q('Conversation', { conversationId: { equalTo: conversationId } }, 2);
        if (found.length !== 1) return refuse('refused', found.length ? 'two conversations for one id' : 'no such conversation');
        thread = found[0];
      }

      const messages = thread.conversationId ? await q('ConversationMessage', { conversationId: { equalTo: thread.conversationId } }) : [];

      // ── OPEN: report what was new, THEN mark the other party's turns read ──
      if (op === 'open') {
        const turns = view(messages, reader);
        const now = new Date().toISOString();
        for (const m of messages) {
          if (m.authorRole !== reader && (m.readAt === null || m.readAt === undefined || m.readAt === '')) {
            await Noodl.Records.save(m.objectId, { readAt: now }, { className: 'ConversationMessage' });
          }
        }
        Outputs.turns = turns;
        Outputs.learnerId = thread.learnerId;
        Outputs.conversationId = thread.conversationId;
        Outputs.done();
        return;
      }

      // ── SEND: refuse rather than trim, under the current notice only ────
      if (r.noticeCurrent !== true) return refuse('notice-not-accepted');
      const body = String(r.body === null || r.body === undefined ? '' : r.body).trim();
      if (body.length === 0) return refuse('empty');
      if (body.length > MAX_CHARS) return refuse('too_long');
      const authorUserId = String(r.authorUserId || '');
      if (!authorUserId) return refuse('refused', 'no author');

      if (!thread.conversationId) {
        const conversationId = newId();
        await Noodl.Records.create('Conversation', {
          conversationId,
          learnerId: thread.learnerId,
          anchorKind: thread.anchorKind,
          anchorId: thread.anchorId,
          subject: deriveSubject(body)
        });
        thread = Object.assign({}, thread, { conversationId });
      }
      const turn = {
        messageId: newId(),
        conversationId: thread.conversationId,
        // TYPED BY THE CALLING FUNCTION'S OWN GRAPH, never derived from roles
        // (the product's L116: a role can change, a message already written cannot).
        authorRole: reader,
        authorUserId,
        body,
        readAt: null
      };
      await Noodl.Records.create('ConversationMessage', turn);
      const createdAt = new Date().toISOString();
      const written = Object.assign({}, turn, { createdAt });
      // The thread as it now stands. Sending marks nothing.
      Outputs.turns = view(messages.concat([written]), reader);
      Outputs.turn = { id: written.messageId, authorRole: reader, body, createdAt };
      Outputs.learnerId = thread.learnerId;
      Outputs.conversationId = thread.conversationId;
      Outputs.anchorKind = thread.anchorKind || '';
      Outputs.anchorId = thread.anchorId || '';
      Outputs.done();
    } catch (e) {
      Outputs.reason = 'refused';
      console.error(tag + ' failed: ' + String((e && e.message) || e) + ' learner=' + String(r.learnerId || '-') + ' conversation=' + String(r.conversationId || '-'));
      Outputs.failed();
    }
  })();
}
